-- Rede de seguranca contra perda SILENCIOSA de dados.
-- O parse tolera corpo vazio (veiculo parado e normal nesta frota). Se
-- NENHUMA chamada da execucao trouxe dado, e improvavel que a frota inteira
-- esteja parada — muito mais provavel que a autenticacao tenha caido.
DO $ck$
DECLARE v_total INT; v_com_dado INT;
BEGIN
    SELECT count(*), count(*) FILTER (WHERE sucesso)
      INTO v_total, v_com_dado
      FROM bronze.tres_s_raw_response
     WHERE metodo = 'HistoricoPosicao'
       AND recebido_em > NOW() - INTERVAL '30 minutes';

    IF v_total >= 5 AND v_com_dado = 0 THEN
        RAISE EXCEPTION
          '[3S] Todas as % chamadas de HistoricoPosicao desta execucao vieram '
          'vazias. Improvavel que a frota inteira esteja parada — suspeite de '
          'token expirado ou permissao revogada. Nenhuma posicao foi carregada.',
          v_total;
    END IF;
END $ck$;

SELECT silver.fn_deriva_eventos_velocidade(CURRENT_DATE - 1, CURRENT_DATE - 1);
SELECT bronze.fn_expurga_posicoes(30);
